(async()=>{const b=await chromium.launch({channel:'msedge',headless:true});const p=await b.newPage({viewport:{width:1000,height:1100}});const errors=[];p.on('pageerror',e=>errors.push(e.message));await p.goto('http://127.0.0.1:5173/preview.html');const result=await p.evaluate(async()=>{const {timeFonts,ensureTimeFont}=await import('/src/fonts.ts');const {drawClock}=await import('/src/render.ts');const results=[];for(const [key,spec] of Object.entries(timeFonts)){await ensureTimeFont(key);const c=document.createElement('canvas');drawClock(c,{timeFont:key},new Date(2026,0,1,12,34,56));results.push({key,loaded:document.fonts.check(spec.weight+' 40px '+spec.family),image:c.toDataURL()});}return results});if(result.some(r=>!r.loaded))throw Error('Font missing');if(new Set(result.map(r=>r.image)).size!==6)throw Error('Identical font render');await p.selectOption('#font','barlow');await p.waitForTimeout(500);await p.screenshot({path:'preview-fonts.png'});for(const url of ['/src/plugin/actions/action1.ts','/src/pages/actions/action1.vue']){const r=await p.request.get('http://127.0.0.1:5173'+url);if(r.status()!==200)throw Error('Compile error '+url)}console.log(JSON.stringify({fonts:result.map(({key,loaded})=>({key,loaded})),errors}));await b.close();if(errors.length)process.exitCode=1})().catch(e=>{console.error(e);process.exitCode=1});